class Utils:
    def __init__(self):
        """Class providing some utility functions throughout the library"""
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UTILS'})

    @staticmethod
    def parameter_value_to_bool(param_name, param_value, value_to_bool_dict, should_raise=True):
        """
        Changes string parameter to a boolean one, according to dictionary provided
        :param param_name: name of parameter (usually from YAML file)
        :param param_value: string value of parameter (usually from YAML file)
        :param value_to_bool_dict: dictionary with strings as keys and booleans as values
        :param should_raise: should raise exception if cannot match key to value
        :return: boolean value based on contents of provided dictionary
        """
        if isinstance(param_value, bool):
            return param_value
        if param_value is None:
            return False
        param_value_lower = param_value.lower()
        if param_value_lower not in value_to_bool_dict:
            if should_raise:
                raise UnsupportedParameterValue(f"{param_name}={param_value}\nSupported options: "
                                                f"{value_to_bool_dict.keys()}")
        return value_to_bool_dict[param_value_lower]

    def get_non_blocking_reader_result(self, reader, as_string=False, timeout=30, interval=1, expect_output=False):
        """
        Get non-blocking reader result
        :param reader: INonBlockingReader instance
        :param as_string: join output list and return as string
        :param timeout: allowed time to wait until reader has not finished
        :param interval: sleep time between checking cmd output
        :param expect_output: if True expects non-empty output
        :return:
        """
        result = []
        end_time = time.time() + timeout
        while not reader.is_finish() and time.time() <= end_time:
            if reader.has_line_without_blocking():
                result += reader.read_lines()
            self.logger.debug(f'Waiting for cmd to end, time: {time.time()}')
            time.sleep(interval)
        if not result and expect_output:
            raise Exception("Output from non-blocking reader empty!")
        if as_string:
            result = self._convert_list_to_string(result)
            self.logger.debug(f"Output cmd string: {result}")
            return result
        self.logger.debug(f'Output lines list: {result}')
        return result

    def _convert_list_to_string(self, lines, join_string="\n"):
        self.logger.debug("Converting list to string")
        result = join_string.join(lines)
        self.logger.debug(f"Output cmd string: {result}")
        return result
